<script setup lang="ts">import {computed} from 'vue';export type OrderItem={id:string;label:string;quantity:number;price:number};const p=withDefaults(defineProps<{items:OrderItem[];currency?:string;discount?:number;tax?:number;title?:string}>(),{currency:'USD',discount:0,tax:0,title:'Order summary'});const subtotal=computed(()=>p.items.reduce((s,i)=>s+i.price*i.quantity,0));const total=computed(()=>subtotal.value-p.discount+p.tax);const money=(n:number)=>new Intl.NumberFormat(undefined,{style:'currency',currency:p.currency}).format(n)</script><template><section class="vx-commerce-panel"><h3>{{title}}</h3><div v-for="item in items" :key="item.id" class="vx-commerce-line"><span>{{item.label}} × {{item.quantity}}</span><strong>{{money(item.price*item.quantity)}}</strong></div><div class="vx-commerce-line"><span>Subtotal</span><span>{{money(subtotal)}}</span></div><div v-if="discount" class="vx-commerce-line"><span>Discount</span><span>−{{money(discount)}}</span></div><div v-if="tax" class="vx-commerce-line"><span>Tax</span><span>{{money(tax)}}</span></div><div class="vx-commerce-line vx-commerce-total"><strong>Total</strong><strong>{{money(total)}}</strong></div><slot name="footer"/></section></template>
